

/* V108 — 3D Tour modal */
(function() {
  var _tourB64Chunks = [
    ""
  ];
  var _tourBlobUrl = null;

  window.openTourModal = function() {
    var modal = document.getElementById('mc-tour-modal');
    modal.style.display = 'flex';
    if (!_tourBlobUrl) {
      try {
        var b64 = _tourB64Chunks.join('');
        var bin = atob(b64);
        var bytes = new Uint8Array(bin.length);
        for (var i = 0; i < bin.length; i++) bytes[i] = bin.charCodeAt(i);
        var blob = new Blob([bytes], {type: 'text/html'});
        _tourBlobUrl = URL.createObjectURL(blob);
      } catch(e) {
        console.error('Tour load error:', e);
      }
    }
    var iframe = document.getElementById('mc-tour-iframe');
    if (_tourBlobUrl && iframe.src !== _tourBlobUrl) iframe.src = _tourBlobUrl;
  };

  window.closeTourModal = function() {
    var modal = document.getElementById('mc-tour-modal');
    modal.style.display = 'none';
  };

  // Wire up the 3D Tour button
  document.addEventListener('DOMContentLoaded', function() {
    var btn = document.getElementById('mc-btn-3dtour');
    if (btn) btn.onclick = function() { window.openTourModal(); };
  });

  // Click outside to close
  document.addEventListener('click', function(e) {
    var modal = document.getElementById('mc-tour-modal');
    if (e.target === modal) window.closeTourModal();
  });

  // Escape to close
  document.addEventListener('keydown', function(e) {
    if (e.key === 'Escape') window.closeTourModal();
  });
})();

